_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated AS SELECT mm.final_marketplace, COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, case WHEN upper(m.final_shipping_status) LIKE \'%RTO%\' OR upper(m.final_shipping_status) LIKE \'%FAILURE%\' OR upper(m.order_status) LIKE \'%UNFULFILLABLE%\' OR upper(m.order_status) LIKE \'%RETURNED TO SELLER%\' OR upper(m.order_status) LIKE \'%RETURNING TO SELLER%\' OR upper(m.order_status) LIKE \'%UNDELIVERED%\' OR (upper(m.order_status) LIKE \'%CANCEL%\' AND upper(m.final_shipping_status) = \'IN TRANSIT\') THEN 1 ELSE 0 end as RTO_flag, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then 1 else 0 end as DTO_flag, case when upper(m.final_shipping_status) like \'%RTO%\' or upper(m.final_shipping_status) like \'%FAILURE%\' or upper(m.order_status) like \'%UNFULFILLABLE%\' or upper(m.order_status) like \'%RETURNED TO SELLER%\' or upper(m.order_status) like \'%RETURNING TO SELLER%\' or upper(m.order_status) like \'%UNDELIVERED%\' or (upper(m.order_status) like \'%CANCEL%\' and upper(m.final_shipping_status) = \'IN TRANSIT\') then m.selling_price ELSE 0 end as RTO_value, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then m.selling_price else 0 end as DTO_value, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM healthymaster-wh-471810.maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM healthymaster-wh-471810.maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN healthymaster-wh-471810.maplemonk.marketplace_mapping mm ON lower(m.marketplace) = lower(mm.marketplace); ALTER TABLE healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, channel, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; UPDATE healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\') THEN \'DADRA AND NAGAR HAVELI\' WHEN UPPER(state) IN (\'DD\', \'DAMAN AND DIU\') THEN \'DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', 